import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { migrateEssencesHandler } from "../handlers/migrateEssencesHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof migrateEssencesHandler>>;
type Vars = void;

export function useMigrateEssences(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: () => migrateEssencesHandler(),
    ...options,
  });
}
